('104c1ec8-b4f2-48c6-a50d-5b45bc16240d'::uuid,'DATE','DATE','A data type representing a calendar date.','A data type representing a valid calendar date.','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('6b542e43-c8f7-41a7-b453-8b38a0767d1a'::uuid,'INTEGER','INTEGER','A data type for whole numbers, including positive, negative and zero values.','A data type representing whole numbers.','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('f2052294-0136-497f-bff1-8542ae5ed5cd'::uuid,'REAL','REAL','A data type for numbers with fractional components.','A data type representing numbers that can include a fractional part.','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.','supplementary_manual_review_required','supplementary_targeted_verified',false,true),
('ce24e284-6b9c-4b25-8f79-6fe8f7f05f32'::uuid,'STRING','STRING','A sequence of characters including letters, digits or other symbols.','A data type representing a sequence of zero or more characters.','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('0c581b6f-2c35-4fa1-b483-48729fe82985'::uuid,'EOF(file)','EOF(file)','A Boolean function indicating whether the end of a file has been reached.','A function that returns TRUE when no more lines can be read from a file, and FALSE when more lines remain.','Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §9.1, p.25; 2027–2029 Pseudocode Guide, §9.1, p.25.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('fc45e99e-835a-4aeb-b481-e59fe4f5c05f'::uuid,'File mode','File mode','A setting determining how an opened file may be read from or written to.','The access mode selected when a file is opened; READ retrieves data, WRITE writes data and replaces existing contents, and APPEND adds data after existing contents.','Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §9.1, p.25; 2027–2029 Pseudocode Guide, §9.1, p.25.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('71a67e1e-8759-4dba-8607-ad1c0b0a2bd2'::uuid,'Text file','Text file','A file storing a sequence of characters that may include end-of-line markers.','A file that stores text as lines, which are read or written consecutively as strings.','Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §9.1, p.25; 2027–2029 Pseudocode Guide, §9.1, p.25.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('90c47865-69c1-4cea-a080-f018c98de11a'::uuid,'CASE selection','CASE statement','A selection construct choosing a branch according to the value or range of an identifier.','A selection statement that chooses the first matching branch according to the value of an identifier; an optional OTHERWISE branch runs if no case matches.','Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §6.2, p.19; 2027–2029 Pseudocode Guide, §6.2, p.19.','supplementary_manual_review_required','supplementary_targeted_verified',false,true),
('d50acf16-d1e5-41f3-b7d7-e25d3dea2396'::uuid,'Count-controlled loop','Count-controlled loop','A loop repeating a known number of times with a counter.','A loop that executes its body for each integer value in a specified range, using a counter.','Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §7.1, p.20; 2027–2029 Pseudocode Guide, §7.1, p.20.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('97295397-cd70-4c60-8b5d-3d2d692cd268'::uuid,'IF selection','IF statement','A selection construct executing a statement or block only when a condition is true.','A selection statement that executes the THEN branch when a Boolean condition is TRUE and, when provided, the ELSE branch when it is FALSE.','Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §6.1, p.18; 2027–2029 Pseudocode Guide, §6.1, p.18.','supplementary_manual_review_required','supplementary_targeted_verified',false,true),
('e5eedbef-8caf-4b2c-bb97-c06a98a573a1'::uuid,'Nested IF','Nested IF','An IF statement placed inside another IF or ELSE branch, allowing the program to make an additional decision only when that branch is reached.','An IF statement placed inside another IF or ELSE branch to test an additional condition within that branch.','Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §6.1, p.18; 2027–2029 Pseudocode Guide, §6.1, p.18.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('b0da2819-b53c-4ba1-a317-c69ed7b0f8b3'::uuid,'Post-condition loop','Post-condition loop','A repetition structure checking its stopping condition after the body executes.','A loop that tests its Boolean condition after executing its body, so the body runs at least once.','Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §7.2, pp.20–21; 2027–2029 Pseudocode Guide, §7.2, pp.20–21.','supplementary_source_screened','supplementary_targeted_verified',true,true),
('d0272651-b95a-40be-8485-4d84ae952726'::uuid,'Pre-condition loop','Pre-condition loop','A repetition structure checking its condition before running the body.','A loop that tests its Boolean condition before each iteration; if the condition is FALSE initially, the body does not run.','Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §7.3, p.21; 2027–2029 Pseudocode Guide, §7.3, p.21.','supplementary_source_screened','supplementary_targeted_verified',true,true)
)
UPDATE public.glossary_terms AS g
SET term = c.new_term,
    definition_en = c.new_definition,
    source_ref = c.new_source,
    definition_evidence_status = c.new_evidence,
    is_glossary_visible = c.new_visible
FROM changes AS c
WHERE g.id = c.id
  AND g.term = c.old_term
  AND g.definition_en = c.old_definition
  AND g.source_ref = c.old_source
  AND g.definition_evidence_status = c.old_evidence
  AND g.is_glossary_visible = c.old_visible
  AND g.status::text = 'approved'
  AND g.is_official_key_term = false
RETURNING g.id, g.term, g.definition_evidence_status, g.is_glossary_visible, g.is_official_key_term;
